// Curated STARTER registry. Expand freely — wrong slugs simply fail to fetch
// and the poller deactivates them after repeated failures (self-healing).
// Verified live from repo captures: stripe(GH), spotify(Lever), ramp(Ashby).
const SEED = [
  { name: 'Stripe',     ats_type: 'greenhouse', slug: 'stripe',     api_base: '' },
  { name: 'Databricks', ats_type: 'greenhouse', slug: 'databricks', api_base: '' },
  { name: 'Figma',      ats_type: 'greenhouse', slug: 'figma',      api_base: '' },
  { name: 'GitLab',     ats_type: 'greenhouse', slug: 'gitlab',     api_base: '' },
  { name: 'Discord',    ats_type: 'greenhouse', slug: 'discord',    api_base: '' },
  { name: 'Spotify',    ats_type: 'lever',      slug: 'spotify',    api_base: '' },
  { name: 'Plaid',      ats_type: 'lever',      slug: 'plaid',      api_base: '' },
  { name: 'Ramp',       ats_type: 'ashby',      slug: 'ramp',       api_base: '' },
  { name: 'OpenAI',     ats_type: 'ashby',      slug: 'openai',     api_base: '' },
  { name: 'Notion',     ats_type: 'ashby',      slug: 'notion',     api_base: '' },
  // v9 Area B2: workday is the only generic multi-tenant type among the newer
  // poller adapters worth bulk-seeding -- amazon/apple/oracle are single-company
  // hardcoded integrations (see Parse Jobs), a 2nd row would mislabel/misroute;
  // smartrecruiters/eightfold use opaque per-tenant ids not derivable from a
  // brand name. These 5 were live-verified, not guessed.
  { name: 'Adobe',      ats_type: 'workday',    slug: 'external_experienced', api_base: 'adobe.wd5' },
  { name: 'Target',     ats_type: 'workday',    slug: 'targetcareers',        api_base: 'target.wd5' },
  { name: 'Walmart',    ats_type: 'workday',    slug: 'WalmartExternal',      api_base: 'walmart.wd5' },
  { name: 'Visa',       ats_type: 'workday',    slug: 'Visa',                 api_base: 'visa.wd5' },
  { name: 'Mastercard', ats_type: 'workday',    slug: 'CorporateCareers',     api_base: 'mastercard.wd1' },
  // s68: Salesforce is reachable via the existing generic Workday adapter --
  // live-verified (real CXS response, total 1486 jobs), zero new code needed.
  { name: 'Salesforce',  ats_type: 'workday',    slug: 'External_Career_Site', api_base: 'salesforce.wd12' },
  // s68: Workable & Recruitee were fully coded, generic, and correctly wired
  // (mkUrl.workable / mkUrl.recruitee both read slug straight from the row,
  // no code changes needed) but had ZERO seeded companies -- these 9 are all
  // live-verified real tenants with real, current job counts (not guessed --
  // several other guessed slugs on both platforms returned a clean 404).
  { name: 'Hugging Face', ats_type: 'workable',  slug: 'huggingface',    api_base: '' },
  { name: 'Skylight',     ats_type: 'workable',  slug: 'skylight-frame', api_base: '' },
  { name: 'WorkMotion',   ats_type: 'workable',  slug: 'workmotion',     api_base: '' },
  { name: 'Curology',     ats_type: 'workable',  slug: 'curology',       api_base: '' },
  { name: 'Tether Operations Limited',  ats_type: 'recruitee', slug: 'tether',             api_base: '' },
  { name: 'Huawei Technologies Canada', ats_type: 'recruitee', slug: 'huaweicanada',       api_base: '' },
  { name: 'Wilcox + Flegel',            ats_type: 'recruitee', slug: 'wilcoxflegel',       api_base: '' },
  { name: 'Great Minds',                ats_type: 'recruitee', slug: 'greatminds',         api_base: '' },
  { name: 'Companion Group',            ats_type: 'recruitee', slug: 'companiongroupltd',  api_base: '' },
];
return SEED.map(c => ({ json: c }));
